import { createFeatureSelector, createSelector } from '@ngrx/store';
export const selectChatState = createFeatureSelector('chat');
export const selectAllMessages = createSelector(selectChatState, state => state.messages);
export const selectSearchResults = createSelector(selectChatState, state => state.searchResults);
export const selectMessageHistory = createSelector(selectChatState, state => state.messageHistory);
export const selectLoading = createSelector(selectChatState, state => state.loading);
export const selectIsStreaming = createSelector(selectChatState, state => state.isStreaming);
export const selectError = createSelector(selectChatState, state => state.error);
export const selectSelectedMessage = createSelector(selectChatState, state => state.selectedMessage);
export const selectSelectedThread = createSelector(selectChatState, state => state.selectedThread);
export const selectThreadMessages = createSelector(selectChatState, state => state.threadMessages);
export const selectTypingUsers = createSelector(selectChatState, state => state.typingUsers);
export const selectHasMoreMessages = createSelector(selectChatState, state => state.hasMore || false);
export const selectReferences = createSelector(selectChatState, state => state.references);
